if (PMPEnable)
  begin : g_pmp_registers
`ifdef CVE2_CUSTOM_PMP_RESET_VALUES
  `include "cve2/cve2_pmp_reset.svh"
`else
  `include "cve2/cve2_pmp_reset_default.svh"
`endif
pmp_mseccfg_t pmp_mseccfg_qA;
pmp_mseccfg_t pmp_mseccfg_qB;
pmp_mseccfg_t pmp_mseccfg_qC;
pmp_mseccfg_t pmp_mseccfg_dA;
pmp_mseccfg_t pmp_mseccfg_dB;
pmp_mseccfg_t pmp_mseccfg_dC;
logic pmp_mseccfg_weA;
logic pmp_mseccfg_weB;
logic pmp_mseccfg_weC;
logic pmp_mseccfg_errA;
logic pmp_mseccfg_errB;
logic pmp_mseccfg_errC;
pmp_cfg_t pmp_cfgA [PMPNumRegions];
pmp_cfg_t pmp_cfgB [PMPNumRegions];
pmp_cfg_t pmp_cfgC [PMPNumRegions];
logic [PMPNumRegions - 1:0] pmp_cfg_lockedA;
logic [PMPNumRegions - 1:0] pmp_cfg_lockedB;
logic [PMPNumRegions - 1:0] pmp_cfg_lockedC;
pmp_cfg_t pmp_cfg_wdataA [PMPNumRegions];
pmp_cfg_t pmp_cfg_wdataB [PMPNumRegions];
pmp_cfg_t pmp_cfg_wdataC [PMPNumRegions];
logic [PMPAddrWidth - 1:0] pmp_addrA [PMPNumRegions];
logic [PMPAddrWidth - 1:0] pmp_addrB [PMPNumRegions];
logic [PMPAddrWidth - 1:0] pmp_addrC [PMPNumRegions];
logic [PMPNumRegions - 1:0] pmp_cfg_weA;
logic [PMPNumRegions - 1:0] pmp_cfg_weB;
logic [PMPNumRegions - 1:0] pmp_cfg_weC;
logic [PMPNumRegions - 1:0] pmp_cfg_errA;
logic [PMPNumRegions - 1:0] pmp_cfg_errB;
logic [PMPNumRegions - 1:0] pmp_cfg_errC;
logic [PMPNumRegions - 1:0] pmp_addr_weA;
logic [PMPNumRegions - 1:0] pmp_addr_weB;
logic [PMPNumRegions - 1:0] pmp_addr_weC;
logic [PMPNumRegions - 1:0] pmp_addr_errA;
logic [PMPNumRegions - 1:0] pmp_addr_errB;
logic [PMPNumRegions - 1:0] pmp_addr_errC;
logic any_pmp_entry_lockedA;
logic any_pmp_entry_lockedB;
logic any_pmp_entry_lockedC;
    for(genvar i = 0; i<PMP_MAX_REGIONS; i++)
          begin : g_exp_rd_data
        if (i<PMPNumRegions)
                  begin : g_implemented_regions
            assign pmp_cfg_rdataA[i] = {pmp_cfgA[i].lock, 2'b00, pmp_cfgA[i].mode, pmp_cfgA[i].exec, pmp_cfgA[i].write, pmp_cfgA[i].read};
            assign pmp_cfg_rdataB[i] = {pmp_cfgB[i].lock, 2'b00, pmp_cfgB[i].mode, pmp_cfgB[i].exec, pmp_cfgB[i].write, pmp_cfgB[i].read};
            assign pmp_cfg_rdataC[i] = {pmp_cfgC[i].lock, 2'b00, pmp_cfgC[i].mode, pmp_cfgC[i].exec, pmp_cfgC[i].write, pmp_cfgC[i].read};
            if (PMPGranularity==0)
                          begin : g_pmp_g0
                assign pmp_addr_rdataA[i] = pmp_addrA[i];
                assign pmp_addr_rdataB[i] = pmp_addrB[i];
                assign pmp_addr_rdataC[i] = pmp_addrC[i];
              end

            else
                          if (PMPGranularity==1)
                              begin : g_pmp_g1

                  always_comb
                    begin
                      pmp_addr_rdataA[i] = pmp_addrA[i];
                      if ((pmp_cfgA[i].mode==PMP_MODE_OFF)||(pmp_cfgA[i].mode==PMP_MODE_TOR))
                        begin
                          pmp_addr_rdataA[i][PMPGranularity - 1:0] = '0;
                        end

                    end

                  always_comb
                    begin
                      pmp_addr_rdataB[i] = pmp_addrB[i];
                      if ((pmp_cfgB[i].mode==PMP_MODE_OFF)||(pmp_cfgB[i].mode==PMP_MODE_TOR))
                        begin
                          pmp_addr_rdataB[i][PMPGranularity - 1:0] = '0;
                        end

                    end

                  always_comb
                    begin
                      pmp_addr_rdataC[i] = pmp_addrC[i];
                      if ((pmp_cfgC[i].mode==PMP_MODE_OFF)||(pmp_cfgC[i].mode==PMP_MODE_TOR))
                        begin
                          pmp_addr_rdataC[i][PMPGranularity - 1:0] = '0;
                        end

                    end
                end

              else
                              begin : g_pmp_g2

                  always_comb
                    begin
                      pmp_addr_rdataA[i] = {pmp_addrA[i], { PMPGranularity - 1 {1'b1} } };
                      if ((pmp_cfgA[i].mode==PMP_MODE_OFF)||(pmp_cfgA[i].mode==PMP_MODE_TOR))
                        begin
                          pmp_addr_rdataA[i][PMPGranularity - 1:0] = '0;
                        end

                    end

                  always_comb
                    begin
                      pmp_addr_rdataB[i] = {pmp_addrB[i], { PMPGranularity - 1 {1'b1} } };
                      if ((pmp_cfgB[i].mode==PMP_MODE_OFF)||(pmp_cfgB[i].mode==PMP_MODE_TOR))
                        begin
                          pmp_addr_rdataB[i][PMPGranularity - 1:0] = '0;
                        end

                    end

                  always_comb
                    begin
                      pmp_addr_rdataC[i] = {pmp_addrC[i], { PMPGranularity - 1 {1'b1} } };
                      if ((pmp_cfgC[i].mode==PMP_MODE_OFF)||(pmp_cfgC[i].mode==PMP_MODE_TOR))
                        begin
                          pmp_addr_rdataC[i][PMPGranularity - 1:0] = '0;
                        end

                    end
                end
          end

        else
                  begin : g_other_regions
            assign pmp_cfg_rdataA[i] = '0;
            assign pmp_cfg_rdataB[i] = '0;
            assign pmp_cfg_rdataC[i] = '0;
            assign pmp_addr_rdataA[i] = '0;
            assign pmp_addr_rdataB[i] = '0;
            assign pmp_addr_rdataC[i] = '0;
          end
      end
    for(genvar i = 0; i<PMPNumRegions; i++)
          begin : g_pmp_csrs
        assign pmp_cfg_weA[i] = csr_we_intA&~pmp_cfg_lockedA[i]& (csr_addrA==(CSR_OFF_PMP_CFG+(i[11:0]>>2))) ;
        assign pmp_cfg_weB[i] = csr_we_intB&~pmp_cfg_lockedB[i]& (csr_addrB==(CSR_OFF_PMP_CFG+(i[11:0]>>2))) ;
        assign pmp_cfg_weC[i] = csr_we_intC&~pmp_cfg_lockedC[i]& (csr_addrC==(CSR_OFF_PMP_CFG+(i[11:0]>>2))) ;
        assign pmp_cfg_wdataA[i].lock = csr_wdata_intA[(i%4)*PMP_CFG_W+7];
        assign pmp_cfg_wdataB[i].lock = csr_wdata_intB[(i%4)*PMP_CFG_W+7];
        assign pmp_cfg_wdataC[i].lock = csr_wdata_intC[(i%4)*PMP_CFG_W+7];

        always_comb
          begin
            unique case (csr_wdata_intA[ (i%4)  * PMP_CFG_W + 3+:2])
              2'b00 : pmp_cfg_wdataA[i].mode = PMP_MODE_OFF;
              2'b01 : pmp_cfg_wdataA[i].mode = PMP_MODE_TOR;
              2'b10 : pmp_cfg_wdataA[i].mode = (PMPGranularity==0) ? PMP_MODE_NA4 : PMP_MODE_OFF;
              2'b11 : pmp_cfg_wdataA[i].mode = PMP_MODE_NAPOT;
              default : pmp_cfg_wdataA[i].mode = PMP_MODE_OFF;
            endcase
          end

        always_comb
          begin
            unique case (csr_wdata_intB[ (i%4)  * PMP_CFG_W + 3+:2])
              2'b00 : pmp_cfg_wdataB[i].mode = PMP_MODE_OFF;
              2'b01 : pmp_cfg_wdataB[i].mode = PMP_MODE_TOR;
              2'b10 : pmp_cfg_wdataB[i].mode = (PMPGranularity==0) ? PMP_MODE_NA4 : PMP_MODE_OFF;
              2'b11 : pmp_cfg_wdataB[i].mode = PMP_MODE_NAPOT;
              default : pmp_cfg_wdataB[i].mode = PMP_MODE_OFF;
            endcase
          end

        always_comb
          begin
            unique case (csr_wdata_intC[ (i%4)  * PMP_CFG_W + 3+:2])
              2'b00 : pmp_cfg_wdataC[i].mode = PMP_MODE_OFF;
              2'b01 : pmp_cfg_wdataC[i].mode = PMP_MODE_TOR;
              2'b10 : pmp_cfg_wdataC[i].mode = (PMPGranularity==0) ? PMP_MODE_NA4 : PMP_MODE_OFF;
              2'b11 : pmp_cfg_wdataC[i].mode = PMP_MODE_NAPOT;
              default : pmp_cfg_wdataC[i].mode = PMP_MODE_OFF;
            endcase
          end
        assign pmp_cfg_wdataA[i].exec = csr_wdata_intA[(i%4)*PMP_CFG_W+2];
        assign pmp_cfg_wdataB[i].exec = csr_wdata_intB[(i%4)*PMP_CFG_W+2];
        assign pmp_cfg_wdataC[i].exec = csr_wdata_intC[(i%4)*PMP_CFG_W+2];
        assign pmp_cfg_wdataA[i].write = pmp_mseccfg_qA.mml ? csr_wdata_intA[(i%4)*PMP_CFG_W+1] : & csr_wdata_intA[ (i%4)  * PMP_CFG_W+:2] ;
        assign pmp_cfg_wdataB[i].write = pmp_mseccfg_qB.mml ? csr_wdata_intB[(i%4)*PMP_CFG_W+1] : & csr_wdata_intB[ (i%4)  * PMP_CFG_W+:2] ;
        assign pmp_cfg_wdataC[i].write = pmp_mseccfg_qC.mml ? csr_wdata_intC[(i%4)*PMP_CFG_W+1] : & csr_wdata_intC[ (i%4)  * PMP_CFG_W+:2] ;
        assign pmp_cfg_wdataA[i].read = csr_wdata_intA[(i%4)*PMP_CFG_W];
        assign pmp_cfg_wdataB[i].read = csr_wdata_intB[(i%4)*PMP_CFG_W];
        assign pmp_cfg_wdataC[i].read = csr_wdata_intC[(i%4)*PMP_CFG_W];

        cve2_csrTMR #(.Width($bits(pmp_cfg_t)), .ResetValue(pmp_cfg_rst[i])) u_pmp_cfg_csr (
            .clk_iA(clk_iA),
            .clk_iB(clk_iB),
            .clk_iC(clk_iC),
            .rst_niA(rst_niA),
            .rst_niB(rst_niB),
            .rst_niC(rst_niC),
            .wr_data_iA({pmp_cfg_wdataA[i]}),
            .wr_data_iB({pmp_cfg_wdataB[i]}),
            .wr_data_iC({pmp_cfg_wdataC[i]}),
            .wr_en_iA(pmp_cfg_weA[i]),
            .wr_en_iB(pmp_cfg_weB[i]),
            .wr_en_iC(pmp_cfg_weC[i]),
            .rd_data_oA(pmp_cfgA[i]),
            .rd_data_oB(pmp_cfgB[i]),
            .rd_data_oC(pmp_cfgC[i]),
            .rd_error_oA(pmp_cfg_errA[i]),
            .rd_error_oB(pmp_cfg_errB[i]),
            .rd_error_oC(pmp_cfg_errC[i]),
            .tmrErrorA(u_pmp_cfg_csrtmrErrorA[i]),
            .tmrErrorB(u_pmp_cfg_csrtmrErrorB[i]),
            .tmrErrorC(u_pmp_cfg_csrtmrErrorC[i])
          );
        assign pmp_cfg_lockedA[i] = pmp_cfgA[i].lock&~pmp_mseccfg_qA.rlb;
        assign pmp_cfg_lockedB[i] = pmp_cfgB[i].lock&~pmp_mseccfg_qB.rlb;
        assign pmp_cfg_lockedC[i] = pmp_cfgC[i].lock&~pmp_mseccfg_qC.rlb;
        if (i<PMPNumRegions-1)
                  begin : g_lower
            assign pmp_addr_weA[i] = csr_we_intA&~pmp_cfg_lockedA[i]& (~ pmp_cfg_lockedA[i+1] | ( pmp_cfgA[i+1].mode!=PMP_MODE_TOR ) ) & (csr_addrA==(CSR_OFF_PMP_ADDR+i[11:0])) ;
            assign pmp_addr_weB[i] = csr_we_intB&~pmp_cfg_lockedB[i]& (~ pmp_cfg_lockedB[i+1] | ( pmp_cfgB[i+1].mode!=PMP_MODE_TOR ) ) & (csr_addrB==(CSR_OFF_PMP_ADDR+i[11:0])) ;
            assign pmp_addr_weC[i] = csr_we_intC&~pmp_cfg_lockedC[i]& (~ pmp_cfg_lockedC[i+1] | ( pmp_cfgC[i+1].mode!=PMP_MODE_TOR ) ) & (csr_addrC==(CSR_OFF_PMP_ADDR+i[11:0])) ;
          end

        else
                  begin : g_upper
            assign pmp_addr_weA[i] = csr_we_intA&~pmp_cfg_lockedA[i]& (csr_addrA==(CSR_OFF_PMP_ADDR+i[11:0])) ;
            assign pmp_addr_weB[i] = csr_we_intB&~pmp_cfg_lockedB[i]& (csr_addrB==(CSR_OFF_PMP_ADDR+i[11:0])) ;
            assign pmp_addr_weC[i] = csr_we_intC&~pmp_cfg_lockedC[i]& (csr_addrC==(CSR_OFF_PMP_ADDR+i[11:0])) ;
          end

        cve2_csrTMR #(.Width(PMPAddrWidth), .ResetValue(pmp_addr_rst[i][33-:PMPAddrWidth])) u_pmp_addr_csr (
            .clk_iA(clk_iA),
            .clk_iB(clk_iB),
            .clk_iC(clk_iC),
            .rst_niA(rst_niA),
            .rst_niB(rst_niB),
            .rst_niC(rst_niC),
            .wr_data_iA(csr_wdata_intA[31-:PMPAddrWidth]),
            .wr_data_iB(csr_wdata_intB[31-:PMPAddrWidth]),
            .wr_data_iC(csr_wdata_intC[31-:PMPAddrWidth]),
            .wr_en_iA(pmp_addr_weA[i]),
            .wr_en_iB(pmp_addr_weB[i]),
            .wr_en_iC(pmp_addr_weC[i]),
            .rd_data_oA(pmp_addrA[i]),
            .rd_data_oB(pmp_addrB[i]),
            .rd_data_oC(pmp_addrC[i]),
            .rd_error_oA(pmp_addr_errA[i]),
            .rd_error_oB(pmp_addr_errB[i]),
            .rd_error_oC(pmp_addr_errC[i]),
            .tmrErrorA(u_pmp_addr_csrtmrErrorA[i]),
            .tmrErrorB(u_pmp_addr_csrtmrErrorB[i]),
            .tmrErrorC(u_pmp_addr_csrtmrErrorC[i])
          );
        assign csr_pmp_cfg_oA[i] = pmp_cfgA[i];
        assign csr_pmp_cfg_oB[i] = pmp_cfgB[i];
        assign csr_pmp_cfg_oC[i] = pmp_cfgC[i];
        assign csr_pmp_addr_oA[i] = {pmp_addr_rdataA[i], 2'b00};
        assign csr_pmp_addr_oB[i] = {pmp_addr_rdataB[i], 2'b00};
        assign csr_pmp_addr_oC[i] = {pmp_addr_rdataC[i], 2'b00};
      end
    assign pmp_mseccfg_weA = csr_we_intA& (csr_addrA==CSR_MSECCFG) ;
    assign pmp_mseccfg_weB = csr_we_intB& (csr_addrB==CSR_MSECCFG) ;
    assign pmp_mseccfg_weC = csr_we_intC& (csr_addrC==CSR_MSECCFG) ;
    assign pmp_mseccfg_dA.mml = pmp_mseccfg_qA.mml ? 1'b1 : csr_wdata_intA[CSR_MSECCFG_MML_BIT];
    assign pmp_mseccfg_dB.mml = pmp_mseccfg_qB.mml ? 1'b1 : csr_wdata_intB[CSR_MSECCFG_MML_BIT];
    assign pmp_mseccfg_dC.mml = pmp_mseccfg_qC.mml ? 1'b1 : csr_wdata_intC[CSR_MSECCFG_MML_BIT];
    assign pmp_mseccfg_dA.mmwp = pmp_mseccfg_qA.mmwp ? 1'b1 : csr_wdata_intA[CSR_MSECCFG_MMWP_BIT];
    assign pmp_mseccfg_dB.mmwp = pmp_mseccfg_qB.mmwp ? 1'b1 : csr_wdata_intB[CSR_MSECCFG_MMWP_BIT];
    assign pmp_mseccfg_dC.mmwp = pmp_mseccfg_qC.mmwp ? 1'b1 : csr_wdata_intC[CSR_MSECCFG_MMWP_BIT];
    assign any_pmp_entry_lockedA = |pmp_cfg_lockedA;
    assign any_pmp_entry_lockedB = |pmp_cfg_lockedB;
    assign any_pmp_entry_lockedC = |pmp_cfg_lockedC;
    assign pmp_mseccfg_dA.rlb = any_pmp_entry_lockedA ? 1'b0 : csr_wdata_intA[CSR_MSECCFG_RLB_BIT];
    assign pmp_mseccfg_dB.rlb = any_pmp_entry_lockedB ? 1'b0 : csr_wdata_intB[CSR_MSECCFG_RLB_BIT];
    assign pmp_mseccfg_dC.rlb = any_pmp_entry_lockedC ? 1'b0 : csr_wdata_intC[CSR_MSECCFG_RLB_BIT];

    cve2_csrTMR #(.Width($bits(pmp_mseccfg_t)), .ResetValue(pmp_mseccfg_rst)) u_pmp_mseccfg (
        .clk_iA(clk_iA),
        .clk_iB(clk_iB),
        .clk_iC(clk_iC),
        .rst_niA(rst_niA),
        .rst_niB(rst_niB),
        .rst_niC(rst_niC),
        .wr_data_iA(pmp_mseccfg_dA),
        .wr_data_iB(pmp_mseccfg_dB),
        .wr_data_iC(pmp_mseccfg_dC),
        .wr_en_iA(pmp_mseccfg_weA),
        .wr_en_iB(pmp_mseccfg_weB),
        .wr_en_iC(pmp_mseccfg_weC),
        .rd_data_oA(pmp_mseccfg_qA),
        .rd_data_oB(pmp_mseccfg_qB),
        .rd_data_oC(pmp_mseccfg_qC),
        .rd_error_oA(pmp_mseccfg_errA),
        .rd_error_oB(pmp_mseccfg_errB),
        .rd_error_oC(pmp_mseccfg_errC),
        .tmrErrorA(u_pmp_mseccfgtmrErrorA),
        .tmrErrorB(u_pmp_mseccfgtmrErrorB),
        .tmrErrorC(u_pmp_mseccfgtmrErrorC)
      );
    assign pmp_mseccfgA = pmp_mseccfg_qA;
    assign pmp_mseccfgB = pmp_mseccfg_qB;
    assign pmp_mseccfgC = pmp_mseccfg_qC;
  end

else
  begin : g_no_pmp_tieoffs
    for(genvar i = 0; i<PMP_MAX_REGIONS; i++)
          begin : g_rdata
        assign pmp_addr_rdataA[i] = '0;
        assign pmp_addr_rdataB[i] = '0;
        assign pmp_addr_rdataC[i] = '0;
        assign pmp_cfg_rdataA[i] = '0;
        assign pmp_cfg_rdataB[i] = '0;
        assign pmp_cfg_rdataC[i] = '0;
      end
    for(genvar i = 0; i<PMPNumRegions; i++)
          begin : g_outputs
        assign csr_pmp_cfg_oA[i] = pmp_cfg_t' (1'b0) ;
        assign csr_pmp_cfg_oB[i] = pmp_cfg_t' (1'b0) ;
        assign csr_pmp_cfg_oC[i] = pmp_cfg_t' (1'b0) ;
        assign csr_pmp_addr_oA[i] = '0;
        assign csr_pmp_addr_oB[i] = '0;
        assign csr_pmp_addr_oC[i] = '0;
      end
    assign pmp_mseccfgA = '0;
    assign pmp_mseccfgB = '0;
    assign pmp_mseccfgC = '0;
    assign u_pmp_addr_csrtmrErrorA = '0;
    assign u_pmp_addr_csrtmrErrorB = '0;
    assign u_pmp_addr_csrtmrErrorC = '0;
    assign u_pmp_cfg_csrtmrErrorA = '0;
    assign u_pmp_cfg_csrtmrErrorB = '0;
    assign u_pmp_cfg_csrtmrErrorC = '0;
    assign u_pmp_mseccfgtmrErrorA = '0;
    assign u_pmp_mseccfgtmrErrorB = '0;
    assign u_pmp_mseccfgtmrErrorC = '0;
  end
assign csr_pmp_mseccfg_oA = pmp_mseccfgA;
assign csr_pmp_mseccfg_oB = pmp_mseccfgB;
assign csr_pmp_mseccfg_oC = pmp_mseccfgC;

